"""Íconos del sistema: trazos de Lucide Icons (https://lucide.dev, licencia ISC) dibujados en un Canvas de Tkinter.

Se dibujan con un subconjunto de la fuente de Lucide (iconos.ttf, 8 KB) registrado solo para este programa, así
que se ven tan nítidos como el texto. Si la fuente no se pudo registrar, se usan los trazos de abajo (polilíneas en
la cuadrícula de 24 × 24) para generar una imagen con bordes suavizados.

    Inicio: house · Estudiantes: graduation-cap · Grupos y materias: book-open · Docentes: presentation
    Inscripciones: clipboard-check · Consultas: search · Reportes: chart-column · Usuarios: users-round
    Personalización: settings-2 · Mis cursos: notebook-text · Plan de evaluación: list-checks
    Captura: pencil-line · Mis calificaciones: file-text · Kárdex: id-card · Mi cuenta: circle-user-round
    Contraseña: eye / eye-off
"""
import os
import shutil
import sys
import tkinter as tk
from pathlib import Path

FAMILIA = "SyllabusIconos"
FUENTE_ICONOS = Path(__file__).with_name("iconos.ttf")  # subconjunto de la fuente de Lucide (solo estos íconos)
CODIGOS = {"inicio": 0xE0F5, "estudiantes": 0xE234, "grupos": 0xE05F, "docentes": 0xE4AE, "inscripciones": 0xE219,
           "consultas": 0xE151, "reportes": 0xE2A3, "usuarios": 0xE46E, "ajustes": 0xE245, "cursos": 0xE598,
           "plan": 0xE1D0, "captura": 0xE4F0, "calificaciones": 0xE0CC, "kardex": 0xE617, "cuenta": 0xE462,
           "ojo": 0xE0BA, "ojo_cerrado": 0xE0BB}
_con_fuente = None  # se decide una vez creada la ventana


def registrar_fuente() -> None:
    """Registra la fuente de íconos solo para este programa (no la instala en el sistema). Se llama antes de crear
    la ventana: así los íconos se dibujan como texto y quedan igual de nítidos que las letras, también en Retina."""
    ruta = str(FUENTE_ICONOS)
    try:
        if sys.platform == "darwin":
            import ctypes
            cf = ctypes.cdll.LoadLibrary("/System/Library/Frameworks/CoreFoundation.framework/CoreFoundation")
            ct = ctypes.cdll.LoadLibrary("/System/Library/Frameworks/CoreText.framework/CoreText")
            cf.CFURLCreateFromFileSystemRepresentation.restype = ctypes.c_void_p
            cf.CFURLCreateFromFileSystemRepresentation.argtypes = [ctypes.c_void_p, ctypes.c_char_p, ctypes.c_long,
                                                                   ctypes.c_bool]
            ct.CTFontManagerRegisterFontsForURL.restype = ctypes.c_bool
            ct.CTFontManagerRegisterFontsForURL.argtypes = [ctypes.c_void_p, ctypes.c_uint32, ctypes.c_void_p]
            datos = ruta.encode("utf-8")
            url = cf.CFURLCreateFromFileSystemRepresentation(None, datos, len(datos), False)
            ct.CTFontManagerRegisterFontsForURL(url, 1, None)  # 1 = kCTFontManagerScopeProcess
        elif sys.platform == "win32":
            import ctypes
            ctypes.windll.gdi32.AddFontResourceExW(ruta, 0x10, 0)  # 0x10 = FR_PRIVATE: solo este proceso
        else:  # Linux: fontconfig lee las fuentes del usuario
            destino = Path(os.path.expanduser("~/.local/share/fonts")) / FUENTE_ICONOS.name
            if not destino.exists():
                destino.parent.mkdir(parents=True, exist_ok=True)
                shutil.copyfile(ruta, destino)
    except Exception:  # noqa: BLE001 - si no se puede, se usan los íconos rasterizados
        pass


def _hay_fuente(widget) -> bool:
    global _con_fuente
    if _con_fuente is None:
        try:
            import tkinter.font
            _con_fuente = FAMILIA in tkinter.font.families(widget)
        except tk.TclError:
            _con_fuente = False
    return _con_fuente

