_CACHE: dict = {}


def _png(nombre: str, color: str, tam: int, grosor: float) -> bytes:
    """PNG con transparencia del ícono a `tam` px, con bordes suavizados (cobertura por distancia al trazo)."""
    import struct
    import zlib
    k, radio = tam / 24, grosor * tam / 24 / 2
    alfa = [0.0] * (tam * tam)
    for linea in TRAZOS.get(nombre, TRAZOS["consultas"]):
        pts = [(linea[i] * k, linea[i + 1] * k) for i in range(0, len(linea), 2)]
        for (x1, y1), (x2, y2) in zip(pts, pts[1:]):
            dx, dy = x2 - x1, y2 - y1
            largo2 = dx * dx + dy * dy or 1e-9
            for py in range(max(0, int(min(y1, y2) - radio - 1)), min(tam, int(max(y1, y2) + radio + 2))):
                for px in range(max(0, int(min(x1, x2) - radio - 1)), min(tam, int(max(x1, x2) + radio + 2))):
                    cx, cy = px + 0.5, py + 0.5
                    t = max(0.0, min(1.0, ((cx - x1) * dx + (cy - y1) * dy) / largo2))
                    ex, ey = cx - (x1 + t * dx), cy - (y1 + t * dy)
                    cobertura = radio + 0.5 - (ex * ex + ey * ey) ** 0.5
                    if cobertura > alfa[py * tam + px]:
                        alfa[py * tam + px] = min(1.0, cobertura)
    r, g, b = (int(color.lstrip("#")[i:i + 2], 16) for i in (0, 2, 4))
    filas = b"".join(b"\x00" + bytes(v for a in alfa[y * tam:(y + 1) * tam] for v in (r, g, b, round(a * 255)))
                     for y in range(tam))

    def bloque(tipo, datos):
        return struct.pack(">I", len(datos)) + tipo + datos + struct.pack(">I", zlib.crc32(tipo + datos) & 0xFFFFFFFF)
    return (b"\x89PNG\r\n\x1a\n" + bloque(b"IHDR", struct.pack(">IIBBBBB", tam, tam, 8, 6, 0, 0, 0))
            + bloque(b"IDAT", zlib.compress(filas)) + bloque(b"IEND", b""))


def dibujar(lienzo: tk.Canvas, nombre: str, color: str, tam: int = 24, grosor: float = 1.8, x0=0, y0=0, etiqueta=None):
    """Dibuja el ícono en el Canvas con su esquina superior izquierda en (x0, y0).

    1. Con la fuente de íconos registrada: como texto (nítido en cualquier pantalla).
    2. Si no: imagen con bordes suavizados generada aquí mismo (el Canvas de Tk redondea las coordenadas de las
       líneas a puntos enteros y las curvas se ven escalonadas)."""
    if nombre in CODIGOS and _hay_fuente(lienzo):
        lienzo.create_text(x0 + tam / 2, y0 + tam / 2, text=chr(CODIGOS[nombre]), fill=color, font=(FAMILIA, -tam),
                           anchor="center", tags=etiqueta or ())
        return
    import base64
    clave = (nombre, color, tam, grosor)
    if clave not in _CACHE:
        _CACHE[clave] = tk.PhotoImage(master=lienzo, data=base64.b64encode(_png(nombre, color, tam, grosor)))
    lienzo.create_image(round(x0), round(y0), image=_CACHE[clave], anchor="nw", tags=etiqueta or ())


def icono(padre, vista_o_nombre: str, color: str, fondo: str, tam: int = 20, grosor: float = 1.8, caja: int | None = None):
    """Canvas con el ícono centrado en un área de `caja` px (por omisión, el tamaño del ícono + 2)."""
    caja = caja or tam + 2
    lienzo = tk.Canvas(padre, width=caja, height=caja, bg=fondo, highlightthickness=0, bd=0)
    margen = (caja - tam) / 2
    dibujar(lienzo, POR_VISTA.get(vista_o_nombre, vista_o_nombre), color, tam, grosor, margen, margen)
    return lienzo
